/// Reads a document of `spec/schemas/v1` by its file's name (without `.json`) into its struct and writes it
/// back as JSON. `None` when no document has that name. What it writes keeps every field it did not know.
///
/// # Errors
///
/// The document does not have the shape of its schema.
#[must_use]
pub fn round_trip(document: &str, value: Value) -> Option<Result<Value, serde_json::Error>> {
    fn go<T: Serialize + for<'de> Deserialize<'de>>(value: Value) -> Result<Value, serde_json::Error> {
        serde_json::to_value(serde_json::from_value::<T>(value)?)
    }
    Some(match document {
        "admin-devices" => go::<AdminDevices>(value),
        "admin-pairing-decision" => go::<AdminPairingDecision>(value),
        "admin-pairings" => go::<AdminPairings>(value),
        "admin-request-decision" => go::<AdminRequestDecision>(value),
        "admin-requests" => go::<AdminRequests>(value),
        "admin-user" => go::<AdminUser>(value),
        "admin-user-create" => go::<AdminUserCreate>(value),
        "admin-user-update" => go::<AdminUserUpdate>(value),
        "admin-users" => go::<AdminUsers>(value),
        "apps" => go::<AppsPage>(value),
        "changes" => go::<Changes>(value),
        "cheat" => go::<CheatSet>(value),
        "cheat-write" => go::<CheatWrite>(value),
        "cheats" => go::<CheatSets>(value),
        "chunk-index" => go::<ChunkIndex>(value),
        "discovery" => go::<Discovery>(value),
        "discovery-peer" => go::<DiscoveryPeer>(value),
        "discovery-request" => go::<DiscoveryRequest>(value),
        "event" => go::<Event>(value),
        "grant" => go::<Grant>(value),
        "handshake" => go::<Handshake>(value),
        "homebrew" => go::<Homebrew>(value),
        "homebrew-page" => go::<HomebrewPage>(value),
        "homebrew-updates-request" => go::<HomebrewUpdatesRequest>(value),
        "invitation" => go::<Invitation>(value),
        "invitation-create" => go::<InvitationCreate>(value),
        "invitations" => go::<Invitations>(value),
        "missing-request" => go::<MissingRequest>(value),
        "pairing-code" => go::<PairingCode>(value),
        "pairing-request" => go::<PairingRequest>(value),
        "pairing-token" => go::<PairingToken>(value),
        "problem" => go::<Problem>(value),
        "request" => go::<TitleRequest>(value),
        "request-create" => go::<RequestCreate>(value),
        "requests" => go::<TitleRequests>(value),
        "save" => go::<Save>(value),
        "saves" => go::<Saves>(value),
        "sections" => go::<Sections>(value),
        "sync" => go::<Sync>(value),
        "sync-collection" => go::<SyncCollection>(value),
        "sync-write" => go::<SyncWrite>(value),
        "title" => go::<Title>(value),
        "title-changes" => go::<TitleChanges>(value),
        "titles" => go::<Titles>(value),
        "upload" => go::<Upload>(value),
        "upload-request" => go::<UploadRequest>(value),
        _ => return None,
    })
}
